package com.lk.esp; import android.app.*; import android.content.Intent; import android.graphics.PixelFormat; import android.hardware.display.*; import android.media.ImageReader; import android.media.projection.*; import android.os.*; import android.util.DisplayMetrics; public class CaptureService extends Service { @Override public IBinder onBind(Intent i) { return null; } @Override public int onStartCommand(Intent intent, int flags, int id) { NotificationChannel ch = new NotificationChannel("c", "Cap", NotificationManager.IMPORTANCE_LOW); getSystemService(NotificationManager.class).createNotificationChannel(ch); startForeground(1, new Notification.Builder(this, "c").setSmallIcon(android.R.drawable.ic_menu_view).build()); MediaProjection mp = ((MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE)).getMediaProjection(Activity.RESULT_OK, intent.getParcelableExtra("data")); DisplayMetrics dm = new DisplayMetrics(); getSystemService(WindowManager.class).getDefaultDisplay().getRealMetrics(dm); ImageReader ir = ImageReader.newInstance(dm.widthPixels, dm.heightPixels, PixelFormat.RGBA_8888, 3); mp.createVirtualDisplay("cap", dm.widthPixels, dm.heightPixels, dm.densityDpi, DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR, ir.getSurface(), null, null); return START_STICKY; } }
